 if(prefix_){prefix_=false;}else if(voice_){voice_->advanceBefore(c,{3,7},[&](){return read(0xd023,1,c);});if(voice_->complete()){auto v=voice_->address();voice_.reset();task_->resume(T::Child::Address,v);}}
